package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app"}) @AutoConfigureMockMvc class AssessmentPolicyHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean AssessmentPolicies policies;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);boolean op=t.equals("op"),shop=t.equals("merchant")||t.equals("staff");var builder=Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").claim("subject_type",op?"operator_account":shop?"staff_account":"user").claim("role",op?"OPERATOR":shop?(t.equals("staff")?"STAFF":"MERCHANT"):"OWNER").claim("app_id",op?"operator-account":shop?"merchant-account":"test-app").expiresAt(Instant.now().plusSeconds(600));if(shop)builder.claim("merchant_id",1L);return builder.build();});}
 String body(){return "{\"merchant_id\":1,\"acquisition_target\":10,\"coupon_target\":20,\"process_requirements\":[\"QUALITY_SIGNED\"],\"grade_thresholds\":[{\"code\":\"A\",\"label\":\"高档\",\"min_score\":\"80.00\"},{\"code\":\"B\",\"label\":\"基础\",\"min_score\":\"0.00\"}],\"source_note\":\"合成规则来源\",\"valid_from\":\"2026-10-31T16:00:00Z\",\"valid_to\":\"2026-12-31T16:00:00Z\"}";}
 @Test void rolesExactQueriesAndStaffCannotReachPolicyService()throws Exception{mvc.perform(get(AssessmentPolicies.PATH)).andExpect(status().isUnauthorized());mvc.perform(get(AssessmentPolicies.PATH).header("Authorization","Bearer owner")).andExpect(status().isForbidden());mvc.perform(get("/api/merchant/assessment/policy").header("Authorization","Bearer staff")).andExpect(status().isForbidden());for(String q:List.of("merchant_id=2","page=0","page=1&page=2","page_size=100"))mvc.perform(get(AssessmentPolicies.PATH+"?"+q).header("Authorization","Bearer op")).andExpect(status().isBadRequest());mvc.perform(get("/api/merchant/assessment/policy?merchant_id=2").header("Authorization","Bearer merchant")).andExpect(status().isBadRequest());verifyNoInteractions(policies);}
 @Test void noStoreReadsDoNotInventScoresAndCreationUsesOneEnvelope()throws Exception{when(policies.list(any(),eq(1))).thenReturn(Map.of("items",List.of(),"total",0,"page",1,"page_size",20));when(policies.current(any())).thenReturn(Map.of("state","UNKNOWN","scoring_available",true,"timezone","Asia/Shanghai"));mvc.perform(get(AssessmentPolicies.PATH).header("Authorization","Bearer op")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get("/api/merchant/assessment/policy").header("Authorization","Bearer merchant")).andExpect(status().isOk()).andExpect(jsonPath("$.data.scoring_available").value(true)).andExpect(jsonPath("$.data.total_score").doesNotExist());when(policies.create(any(),anyString(),any())).thenReturn(new com.fasterxml.jackson.databind.ObjectMapper().readTree("{\"code\":0,\"data\":{\"id\":1}}"));mvc.perform(post(AssessmentPolicies.PATH).header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body())).andExpect(status().isOk()).andExpect(jsonPath("$.data.id").value(1)).andExpect(jsonPath("$.data.data").doesNotExist());}
 @Test void targetsGradesMonthAndKeysAreStrictBeforeAnyWrite()throws Exception{mvc.perform(post(AssessmentPolicies.PATH).header("Authorization","Bearer op").contentType("application/json").content(body())).andExpect(status().isBadRequest());for(String b:List.of(body().replace("10,","0,"),body().replace("10,","1.5,"),body().replace("80.00","100.01"),body().replace("16:00:00Z","15:00:00Z"),body().replace("\"merchant_id\":1,","\"merchant_id\":1,\"weights\":40,"),body()+"{}"))mvc.perform(post(AssessmentPolicies.PATH).header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(b)).andExpect(status().isBadRequest());verifyNoInteractions(policies);}
}
